/* ---------- 18 code block ---------- */
{
  const pre = $('#code-pre');
  const code = [
    '<span class="k">export function</span> <span class="f">useAgentStatus</span>(id: <span class="ty">string</span>) {',
    '  <span class="k">const</span> [status, setStatus] = <span class="f">useState</span>&lt;<span class="ty">Status</span>&gt;(<span class="s">"idle"</span>);',
    '',
    '  <span class="f">useEffect</span>(() =&gt; {',
    '    <span class="k">const</span> stream = agent.<span class="f">subscribe</span>(id);',
    '    stream.<span class="f">on</span>(<span class="s">"update"</span>, (s) =&gt; <span class="f">setStatus</span>(s.state));',
    '    <span class="k">return</span> () =&gt; stream.<span class="f">close</span>();',
    '  }, [id]);',
    '',
    '  <span class="k">return</span> status;',
    '}'
  ];
  const diff = [
    ['','<span class="k">export function</span> <span class="f">useAgentStatus</span>(id: <span class="ty">string</span>) {'],
    ['','  <span class="k">const</span> [status, setStatus] = <span class="f">useState</span>&lt;<span class="ty">Status</span>&gt;(<span class="s">"idle"</span>);'],
    ['add','  <span class="k">const</span> [error, setError] = <span class="f">useState</span>&lt;<span class="ty">Error</span> | <span class="ty">null</span>&gt;(<span class="k">null</span>);'],
    ['',''],
    ['','  <span class="f">useEffect</span>(() =&gt; {'],
    ['','    <span class="k">const</span> stream = agent.<span class="f">subscribe</span>(id);'],
    ['del','    stream.<span class="f">on</span>(<span class="s">"update"</span>, (s) =&gt; <span class="f">setStatus</span>(s.state));'],
    ['add','    stream.<span class="f">on</span>(<span class="s">"update"</span>, (s) =&gt; <span class="f">setStatus</span>(s.state));'],
    ['add','    stream.<span class="f">on</span>(<span class="s">"error"</span>, <span class="f">setError</span>);'],
    ['','    <span class="k">return</span> () =&gt; stream.<span class="f">close</span>();'],
    ['','  }, [id]);'],
    ['del','  <span class="k">return</span> status;'],
    ['add','  <span class="k">return</span> { status, error };'],
    ['','}']
  ];
  const show = v => { pre.innerHTML = v === 'diff' ? diff.map(([c, l]) => `<span class="cl ${c}">${l || ' '}</span>`).join('') : code.map(l => `<span class="cl">${l || ' '}</span>`).join(''); pre.classList.remove('enter'); pre.offsetWidth; pre.classList.add('enter'); };
  tabHandlers.code = v => morph(pre.closest('.panel'), () => show(v));
  $('#code-copy').addEventListener('click', async () => { if (await copyText(pre.textContent)){ Sound.play('copy'); showToast('Copied'); } });
  show('code');
}
